// wf.listing.analyze > "Plan": one item per waiting file. Photos go to wf.intake.photos; other kinds
// are left pending until their intake workflows exist (voice, video and PDF later in phase 4).
const s = $input.first().json;
if (!s.job_id) return [];                                   // job not queued any more (already running or done)
const photos = (s.uploads || []).filter((u) => u.kind === 'photo');
if (!photos.length) return [{ json: { none: true } }];
return photos.map((u) => ({ json: { job_id: s.job_id, listing_id: s.input.listing_id, upload_id: u.upload_id, key: u.key,
  media_url: s.media_url } }));

// wf.listing.analyze > "Job failed": a step failed in a way the worker did not plan for. The job ends as
// failed (not retried), with the redacted error, so it never stays "running".
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const s = $('Start job').first().json;
const msg = redactPg(errorText($input.first().json)).slice(0, 500) || 'worker step failed without a message';
return [{ json: { params: [s.job_id, 'failed', JSON.stringify({ failed_step: true }), msg, false] } }];

// wf.listing.analyze > "Summarize": job output, the raw uploads to delete, and whether to retry.
// Raw uploads carry EXIF (GPS, device) and unblurred faces: they are deleted once a decision is stored
// (processed or rejected). Missing files stay pending; a transient failure retries the job (spec 5.6).
const s = $('Start job').first().json;
const results = $input.all().map((i) => i.json).filter((r) => r && r.upload_id);
const count = (st) => results.filter((r) => r.status === st).length;
const transient = count('transient');
const output = { listing_id: s.input.listing_id, processed: count('processed'), rejected: count('rejected'),
  missing: count('missing'), transient, files: results.map(({ key, ...r }) => r) };
const del = results.filter((r) => ['processed', 'rejected'].includes(r.status)).map((r) => r.key);
return [{ json: { job_id: s.job_id, output, delete_keys: del, transient,
  error: transient ? `${transient} file(s) not processed: ${results.find((r) => r.status === 'transient').error}` : null,
  delete_url: `${String(s.media_url).replace(/\/+$/, '')}/v1/storage/delete` } }];

// wf.listing.analyze > "Extract input"
const s = $('Summarize').first().json;
return [{ json: { listing_id: s.output.listing_id, job_id: s.job_id } }];

// wf.listing.analyze > "Finish input": parameters of app.job_finish.
// The job fails and is retried when a photo or the extraction hit a transient failure (model or
// service unavailable, spec 5.6). A non-transient extraction failure (invalid output twice) fails
// the job without retry; photos already stored stay stored and a new analysis repeats the extraction.
const x = $('Summarize').first().json;
const d = $('Delete raw uploads').first().json || {};
const e = $input.first().json || {};
const output = { ...x.output, raw_deleted: x.delete_keys.length ? (d.statusCode === 200 ? x.delete_keys.length : 0) : 0,
  extraction: { status: e.status || 'failed', issues: e.issues || [], rent_scope: e.rent_scope ?? null, error: e.error || null } };
if (x.delete_keys.length && d.statusCode !== 200) output.raw_delete_error = `media service answered ${d.statusCode || 'nothing'}`;
const transient = !!x.transient || (e.ok === false && !!e.transient);
const errors = [x.error, e.ok === false ? e.error : null].filter(Boolean);
const failed = transient || e.ok === false;
return [{ json: { params: [x.job_id, failed ? 'failed' : 'succeeded', JSON.stringify(output), errors.join('; ') || null, transient] } }];
